const ctx = $json;

const template = `You are a customer support assistant for ${ctx.tenant_config.tenant_name || 'this company'}. Answer the customer's question using ONLY the information in the "Retrieved Context" below. Do not use any outside knowledge.

Rules:
- If the retrieved context fully answers the question, answer clearly and concisely, citing the relevant plan/section by name where natural.
- If the retrieved context only partially answers it, answer what you can and clearly state what's missing.
- If the retrieved context does not contain the answer at all, say so plainly — do not guess or fill the gap from general knowledge.
- Never invent specific numbers, prices, or policy details not present in the retrieved context.
- Keep the tone helpful and direct, matching a professional support agent.

Retrieved Context:
${ctx.retrieved_context || '(no relevant context found)'}

Conversation so far:
${ctx.conversation_history || '(none)'}

Customer's latest message:
${ctx.text}`;

return [{ json: { ...ctx, generation_prompt: template } }];

const generatedText = $json.text;
const original = $('[RAG] - Build Retrieved Context').item.json;

// Simple, explainable confidence heuristic — NOT self-reported by the LLM.
// Starts from retrieval_score (how well context matched the question),
// then penalizes for risk flags or a clearly empty/refused answer.
let confidence_score = original.retrieval_score;

if (original.risk_flags && original.risk_flags.length > 0) {
  confidence_score -= 0.15;
}

const noContextPhrases = ['does not contain', 'no relevant', "don't have", 'cannot find'];
if (noContextPhrases.some(p => generatedText.toLowerCase().includes(p))) {
  confidence_score -= 0.3;
}

confidence_score = Math.max(0, Math.min(1, confidence_score));

return [{
  json: {
    ...original,
    response_text: generatedText,
    confidence_score
  }
}];

