const decision = $json;

let conversation = [];
let customer = {};

try {
  conversation = $('[CHAT] - Build Conversation Context').item.json.conversation_history
    || '';
} catch (e) {}

try {
  customer = $('[CHAT] - Build Conversation Context').item.json.customer_context
    || {};
