}];

const result = $json.output || {};

const original =
  $('[ESCALATION] - Build Intake Context').item.json;

const previous =
  original.intake_context || {};

const previousMissing =
  Array.isArray(previous.missing_information)
    ? previous.missing_information
    : [];

const provided =
  Array.isArray(result.provided_information)
    ? result.provided_information
    : [];

const stillMissing =
  Array.isArray(result.still_missing_information)
    ? result.still_missing_information
    : previousMissing;

const evidence =
  Array.isArray(result.evidence_received)
    ? result.evidence_received
    : [];

return [{
  json: {
    ...original,

    update_analysis: {
      provided_information: provided,

      still_missing_information: stillMissing,

      case_ready:
        result.case_ready === true,

      customer_action_required:
        result.customer_action_required ?? !(
          result.case_ready === true
        ),

      next_action:
        result.next_action ||
        (
          result.case_ready === true
            ? 'prepare_case_for_human_agent'
            : 'ask_customer_for_missing_information'
        ),

      evidence_received: evidence
    }
  }
}];

const analysis = $json.update_analysis;
const caseData = $json.active_escalation_case;

return [{
  json: {
    ...$json,

    escalation_state: 'READY_FOR_AGENT',

    case_update: {
      case_id: caseData.case_id,
      status: 'ready_for_agent',
      provided_information: analysis.provided_information,
      remaining_information: analysis.still_missing_information,
      evidence_received: analysis.evidence_received
    }
  }
}];

const analysis = $json.update_analysis;
const caseData = $json.active_escalation_case;

return [{
  json: {
    ...$json,

    escalation_state: 'AWAITING_CUSTOMER_INFO',

    case_update: {
      case_id: caseData.case_id,
      status: 'awaiting_customer_info',
